"use client"

import * as React from "react"

type GlimmHtmlInCanvasProps = {
  className?: string
  autoPlay?: boolean
}

function GlimmHtmlInCanvas({ className, autoPlay = true }: GlimmHtmlInCanvasProps) {
  const videoRef = React.useRef<HTMLVideoElement>(null)

  React.useEffect(() => {
    if (!autoPlay || !videoRef.current) return
    const video = videoRef.current
    const observer = new IntersectionObserver(([entry]) => {
      if (entry?.isIntersecting) void video.play().catch(() => undefined)
      else video.pause()
    }, { threshold: 0.3 })
    observer.observe(video)
    return () => observer.disconnect()
  }, [autoPlay])

  return (
    <main className={className} style={{ alignItems: "center", background: "#fff", display: "flex", justifyContent: "center", minHeight: "100vh", padding: "48px 32px", width: "100%" }}>
      <video
        ref={videoRef}
        aria-label="An invoice paid banner drops into an app as the glimm band breaks across, and the page gathers toward it, ripples and settles"
        loop
        muted
        playsInline
        poster="https://cdn.21st.dev/assets/mirror/3f/3fcd14fe995e6cad7b9f9f213f72722cbee531ed3e8611cbdbd9ccaeb4f34e30.jpg"
        preload="metadata"
        src="https://cdn.21st.dev/assets/mirror/96/9634d397fe221306949a7f4815c29fc8c2ab2224f818409d5fb1434f558e277a.mp4"
        style={{ aspectRatio: "16 / 10", background: "#f7f7f7", borderRadius: "12px", boxShadow: "0 0 0 0.5px rgba(0,0,0,0.08)", display: "block", maxWidth: "634px", objectFit: "cover", width: "100%" }}
      />
    </main>
  )
}

export { GlimmHtmlInCanvas }
export default GlimmHtmlInCanvas

